import {HabitatView} from './view.mjs';
const $=id=>document.getElementById(id);let worker,view,ready=false,paused=false,top=false,trace=[],state,neural,validating=false,toastTimer;
const fmt=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toFixed(1).padStart(4,'0')}`;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2600);}
function send(type,data={}){worker?.postMessage({type,...data});}
function pause(){if(!ready||validating)return;send('pause',{value:!paused});}
function setup(){try{view=new HabitatView($('scene'),(x,z)=>{if(ready&&!validating){send('food',{x,z});toast('已放置糖源');}});worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data:d})=>{
 if(d.type==='loading'){$('progress').style.width=`${d.progress*100}%`;$('load-message').textContent=d.message;}
 if(d.type==='ready'){ready=true;$('loading').hidden=true;for(const id of ['pause','reset','sugar','sensory-cut','motor-cut','validate','export'])$(id).disabled=false;$('pause').textContent='Ⅱ 暂停';$('state-label').textContent='模拟运行中';toast('全脑连接已校验 · 模型已启动');}
 if(d.type==='state'){state=d.world;neural=d.neural;trace=d.trace;view.update(state);$('ratio').textContent=d.performance.ratio.toFixed(2)+'×';$('motor-rate').textContent=Math.round(state.signal);$('motor-bar').style.width=Math.min(100,state.signal/150*100)+'%';$('fed').textContent=state.fed.toFixed(2);$('simtime').textContent=fmt(state.time);$('active').textContent=d.neural.active.toLocaleString()+' 活跃';$('spikes').textContent=d.neural.total.toLocaleString()+' spikes';$('behavior').textContent=state.signal>10?(state.contact?'摄食中':'口器伸出'):state.blind?'感觉切断':state.silenced?'MN9 沉默':'探索中';if(!paused&&!validating)$('state-label').textContent=state.blind?'感觉输入已切断':state.pulse?'糖感觉刺激中':state.contact?'接触糖源':'模拟运行中';}
 if(d.type==='paused'){paused=d.value;$('pause').textContent=paused?'▶ 继续':'Ⅱ 暂停';$('state-label').textContent=paused?'已暂停':'模拟运行中';}
 if(d.type==='reset'){view.reset();trace=[];$('sensory-cut').checked=false;$('motor-cut').checked=false;toast('培养皿与神经状态已重置');}
 if(d.type==='validationProgress'){validating=true;$('validation').hidden=false;$('validation-state').textContent=d.message;$('state-label').textContent='独立验证中';$('validate').disabled=true;}
 if(d.type==='validation'){validating=false;$('validate').disabled=false;$('validation-state').textContent='验证完成';$('state-label').textContent=paused?'已暂停':'模拟运行中';const labels={baseline:'无感觉输入',sugar:'糖刺激 100 Hz',silenced:'糖刺激 + MN9 沉默'};$('validation-content').replaceChildren(...d.rows.map(r=>{const card=document.createElement('div');card.className='validation-card';const label=document.createElement('span'),rate=document.createElement('strong'),detail=document.createElement('small');label.textContent=labels[r.condition];rate.textContent=r.mn9Hz+' Hz';detail.textContent=`MN9 输出 · 模型 1 秒 / 实际 ${(r.wallMs/1000).toFixed(2)} 秒`;card.append(label,rate,detail);return card;}));$('validation').scrollIntoView({behavior:'smooth',block:'nearest'});toast('独立行为验证已完成');}
 if(d.type==='export'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d.record,null,2)],{type:'application/json'}));a.download='flylab-digital-fly.json';document.body.append(a);a.click();a.remove();toast('本轮记录已生成，已请求下载');setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 if(d.type==='error')showError(d.message);
 };worker.onerror=e=>showError(e.message||'神经工作线程无法启动');send('load');requestAnimationFrame(render);
 }catch(e){showError('无法建立 3D 场景：'+e.message);}}
function showError(message){$('loading').hidden=false;$('load-title').textContent='暂时无法启动';$('load-message').textContent=message;$('retry').hidden=false;$('state-label').textContent='加载失败';$('progress').style.background='#e8bb6c';}
$('retry').onclick=()=>location.reload();$('pause').onclick=pause;$('reset').onclick=()=>{send('reset');};$('sugar').onclick=()=>{send('pulse');toast('150 Hz 糖刺激 · 持续 2 秒模型时间');};$('sensory-cut').onchange=e=>{send('blind',{value:e.target.checked});toast(e.target.checked?'感觉输入已切断':'感觉输入已恢复');};$('motor-cut').onchange=e=>{send('silence',{value:e.target.checked});toast(e.target.checked?'MN9 已沉默':'MN9 已恢复');};$('camera').onclick=()=>{top=!top;view?.setView(top);$('camera').textContent=top?'斜视 ↗':'俯视 ↗';};$('trail').onchange=e=>{if(view)view.path.visible=e.target.checked;};$('validate').onclick=()=>{if(ready&&!validating){validating=true;$('validate').disabled=true;$('validation-content').replaceChildren();send('validate');}};$('export').onclick=()=>send('export');$('methods').onclick=()=>$('info').showModal();$('close').onclick=()=>$('info').close();
window.addEventListener('keydown',e=>{if(e.target.matches('input,select,button')||$('info').open)return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)pause();}if(e.key.toLowerCase()==='s'&&ready&&!e.repeat)send('pulse');});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&ready&&!paused)send('pause',{value:true});});
function context(id){const c=$(id),r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio,2);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);}const g=c.getContext('2d');g.setTransform(d,0,0,d,0,0);g.clearRect(0,0,r.width,r.height);return [g,r.width,r.height];}
function drawChart(){const [g,w,h]=context('trace');g.font='10px monospace';g.fillStyle='#819880';for(let y=0;y<4;y++){const yy=10+y*(h-25)/3;g.strokeStyle='#344633';g.lineWidth=.6;g.beginPath();g.moveTo(30,yy);g.lineTo(w,yy);g.stroke();g.fillText(String(150-y*50),0,yy+3);}for(const [field,color] of [['input','#e8bb6c'],['mn9Hz','#c1ef8f']]){g.strokeStyle=color;g.lineWidth=1.7;g.beginPath();trace.forEach((p,i)=>{const x=30+i/99*(w-32),y=h-15-Math.min(150,p[field])/150*(h-25);if(i===0)g.moveTo(x,y);else g.lineTo(x,y);});g.stroke();}}
function drawBrain(){const [g,w,h]=context('brain-view');const hash=(i,s)=>{let n=Math.imul(i+s,2654435761);return ((n^(n>>>16))>>>0)/4294967295;};for(let i=0;i<120;i++){const side=i<60?-1:1,angle=hash(i,1)*Math.PI*2,r=Math.sqrt(hash(i,9));const x=w/2+side*w*.17+Math.cos(angle)*r*w*.17,y=h*.5+Math.sin(angle)*r*h*.4;g.fillStyle='#66865844';g.beginPath();g.arc(x,y,1.2,0,Math.PI*2);g.fill();}for(const a of neural?.activity||[]){const side=a.index%2?-1:1,angle=hash(a.index,1)*Math.PI*2,r=Math.sqrt(hash(a.index,9)),x=w/2+side*w*.17+Math.cos(angle)*r*w*.17,y=h*.5+Math.sin(angle)*r*h*.4;g.fillStyle='#c1ef8f';g.globalAlpha=Math.min(1,.3+a.count*.06);g.beginPath();g.arc(x,y,Math.min(3,1+a.count*.09),0,Math.PI*2);g.fill();}g.globalAlpha=1;}
let count=0;function render(){view?.render();if(count++%4===0){drawChart();drawBrain();}requestAnimationFrame(render);}setup();
